'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { getProspects, createProspect, deleteProspect, updateProspect, grantConsent, revokeConsent, checkConsent, createLead } from '@/lib/api';
import Button from '@/components/Button';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import Toast from '@/components/Toast';

export default function ProspectsPage() {
  const router = useRouter();
  const [prospects, setProspects] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All Status');
  const [interestFilter, setInterestFilter] = useState('All Interest');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' | 'info' } | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [showEditForm, setShowEditForm] = useState(false);
  const [editingProspect, setEditingProspect] = useState<any>(null);
  const [newProspect, setNewProspect] = useState({
    name: '', position: '', company: '', yacht: '',
    email: '', phone: '', whatsapp: '', linkedin: '',
    country: '', status: 'New', interest: 'Medium',
    emailConsent: false, whatsappConsent: false, linkedinConsent: false,
  });

  useEffect(() => {
    const fetchProspects = async () => {
      try {
        const data = await getProspects();
        if (data.error) {
          console.error('API error:', data.error);
          setError(data.error);
          setProspects([]);
        } else {
          setProspects(Array.isArray(data) ? data : []);
          setError(null);
        }
      } catch (error: any) {
        console.error('Failed to fetch prospects:', error);
        setError(error.message || 'Failed to load prospects');
        setProspects([]);
      } finally {
        setLoading(false);
      }
    };
    fetchProspects();
  }, []);

  const filteredProspects = Array.isArray(prospects) ? prospects.filter(p => {
    const matchesSearch = (p.name ?? '').toString().toLowerCase().includes(searchTerm.toLowerCase()) ||
                         (p.company ?? '').toString().toLowerCase().includes(searchTerm.toLowerCase()) ||
                         (p.email ?? '').toString().toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'All Status' || p.status === statusFilter;
    const matchesInterest = interestFilter === 'All Interest' || p.interest === interestFilter;
    return matchesSearch && matchesStatus && matchesInterest;
  }) : [];

  const handleDelete = async (id: number) => {
    await deleteProspect(id);
    setProspects(prospects.filter(p => p.id !== id));
    setToast({ message: 'Prospect deleted successfully', type: 'success' });
  };

  const handleStatusChange = (id: number, newStatus: string) => {
    setProspects(prospects.map(p => p.id === id ? { ...p, status: newStatus } : p));
    setToast({ message: 'Status updated successfully', type: 'success' });
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-950 p-6">
        <div className="bg-gray-800 border border-gray-700 rounded-xl p-4">
          <LoadingSkeleton />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-950 p-6">
        <div className="bg-red-900/30 border border-red-700 rounded-xl p-4">
          <p className="text-sm text-red-400">Error: {error}</p>
        </div>
      </div>
    );
  }

  const statusColor: Record<string, string> = {
    New: "bg-gray-700 text-gray-300",
    Contacted: "bg-gray-700 text-gray-300",
    Responded: "bg-gray-700 text-gray-300",
    Interested: "bg-gray-700 text-gray-300",
    Qualified: "bg-gray-700 text-gray-300",
    "Meeting Scheduled": "bg-gray-700 text-gray-300",
    "Follow-up Required": "bg-gray-700 text-gray-300",
    "Not Interested": "bg-gray-700 text-gray-300",
  };

  return (
    <div className="min-h-screen bg-gray-950 p-6">
      <button
        onClick={() => window.history.back()}
        className="flex items-center gap-2 text-sm text-gray-400 hover:text-white mb-4"
      >
        ← Back
      </button>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-base font-semibold text-white">Prospects</h2>
        <div className="flex gap-2">
          <label className="cursor-pointer bg-gray-700 text-white text-sm px-4 py-2 rounded-lg hover:bg-gray-600">
            📁 Import CSV
            <input
              type="file"
              accept=".csv"
              className="hidden"
              onChange={async (e) => {
                const file = e.target.files?.[0];
                if (!file) return;
                const text = await file.text();
                const lines = text.split('\n').filter(l => l.trim());
                const headers = lines[0].split(',').map(h => (h.trim() ?? '').toString().toLowerCase());
                let added = 0;
                for (let i = 1; i < lines.length; i++) {
                  const values = lines[i].split(',').map(v => v.trim());
                  const prospect: any = {};
                  headers.forEach((h, idx) => { prospect[h] = values[idx] || ''; });
                  if (prospect.name) {
                    const result = await createProspect({ ...prospect, status: 'New', interest: 'Medium' });
                    setProspects(prev => [...prev, result]);
                    added++;
                  }
                }
                setToast({ message: `${added} prospects imported!`, type: 'success' });
              }}
            />
          </label>
          <Button variant="primary" onClick={() => setShowAddForm(!showAddForm)}>
            {showAddForm ? 'Cancel' : '+ Add prospect'}
          </Button>
        </div>
      </div>

      {showAddForm && (
        <div className="bg-gray-800 border border-gray-700 rounded-xl p-4 mb-4">
          <p className="text-sm font-medium text-white mb-4">Add New Prospect</p>
          <div className="grid grid-cols-3 gap-3">
            {[
              { key: 'name', label: 'Name', placeholder: 'John Smith' },
              { key: 'position', label: 'Position', placeholder: 'Manager' },
              { key: 'company', label: 'Company', placeholder: 'Company name' },
              { key: 'yacht', label: 'Industry / Notes', placeholder: 'Industry or notes' },
              { key: 'email', label: 'Email', placeholder: 'email@example.com' },
              { key: 'phone', label: 'Phone', placeholder: '+1 234 567 8900' },
              { key: 'whatsapp', label: 'WhatsApp', placeholder: '+8801XXXXXXXXX (include country code)' },
              { key: 'country', label: 'Country', placeholder: 'Italy' },
            ].map((field) => (
              <div key={field.key}>
                <label className="text-xs text-gray-400 mb-1 block">{field.label}</label>
                <input
                  type="text"
                  placeholder={field.placeholder}
                  value={(newProspect as any)[field.key]}
                  onChange={(e) => setNewProspect({...newProspect, [field.key]: e.target.value})}
                  className="w-full border border-gray-700 bg-gray-900 rounded-lg px-3 py-2 text-sm text-white placeholder-gray-500 outline-none"
                />
              </div>
            ))}
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={newProspect.emailConsent}
                onChange={(e) => setNewProspect({...newProspect, emailConsent: e.target.checked})}
                className="w-4 h-4"
              />
              <span className="text-sm text-gray-400">Email consent granted</span>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={newProspect.whatsappConsent}
                onChange={(e) => setNewProspect({...newProspect, whatsappConsent: e.target.checked})}
                className="w-4 h-4"
              />
              <span className="text-sm text-gray-400">WhatsApp consent granted</span>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={newProspect.linkedinConsent}
                onChange={(e) => setNewProspect({...newProspect, linkedinConsent: e.target.checked})}
                className="w-4 h-4"
              />
              <span className="text-sm text-gray-400">LinkedIn consent granted</span>
            </div>
          </div>
          <div className="mt-4 flex gap-2">
            <Button variant="primary" onClick={async () => {
              if (!newProspect.name) { setToast({ message: 'Name is required', type: 'error' }); return; }
              const result = await createProspect(newProspect);
              setProspects([...prospects, result]);
              setShowAddForm(false);
              setNewProspect({ name: '', position: '', company: '', yacht: '', email: '', phone: '', whatsapp: '', linkedin: '', country: '', status: 'New', interest: 'Medium', emailConsent: false, whatsappConsent: false, linkedinConsent: false });

              // Grant email consent if checked
              if (newProspect.emailConsent && result.id) {
                await grantConsent({ consent_type: 'email', prospect_id: result.id, source: 'manual' });
              }

              // Grant WhatsApp consent if checked
              if (newProspect.whatsappConsent && result.id) {
                await grantConsent({ consent_type: 'whatsapp', prospect_id: result.id, source: 'manual' });
              }

              // Grant LinkedIn consent if checked
              if (newProspect.linkedinConsent && result.id) {
                await grantConsent({ consent_type: 'linkedin', prospect_id: result.id, source: 'manual' });
              }

              setToast({ message: 'Prospect added!', type: 'success' });
            }}>
              Save Prospect
            </Button>
          </div>
        </div>
      )}

      {showEditForm && editingProspect && (
        <div className="bg-gray-800 border border-gray-700 rounded-xl p-4 mb-4">
          <p className="text-sm font-medium text-white mb-4">Edit Prospect</p>
          <div className="grid grid-cols-3 gap-3">
            {[
              { key: 'name', label: 'Name' },
              { key: 'position', label: 'Position' },
              { key: 'company', label: 'Company' },
              { key: 'email', label: 'Email' },
              { key: 'phone', label: 'Phone' },
              { key: 'whatsapp', label: 'WhatsApp' },
              { key: 'country', label: 'Country' },
              { key: 'status', label: 'Status', select: true, options: ['New', 'Contacted', 'Responded', 'Interested', 'Qualified', 'Meeting Scheduled', 'Follow-up Required', 'Not Interested'] },
              { key: 'interest', label: 'Interest', select: true, options: ['Low', 'Medium', 'High', 'Very High'] },
              { key: 'notes', label: 'Notes', textarea: true },
            ].map((field) => (
              <div key={field.key}>
                <label className="text-xs text-gray-400 mb-1 block">{field.label}</label>
                {field.select ? (
                  <select
                    value={(editingProspect as any)[field.key] || ''}
                    onChange={(e) => setEditingProspect({...editingProspect, [field.key]: e.target.value})}
                    className="w-full border border-gray-700 bg-gray-900 rounded-lg px-3 py-2 text-sm text-white outline-none"
                  >
                    {field.options?.map((opt) => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.textarea ? (
                  <textarea
                    placeholder={field.label}
                    value={(editingProspect as any)[field.key] || ''}
                    onChange={(e) => setEditingProspect({...editingProspect, [field.key]: e.target.value})}
                    className="w-full border border-gray-700 bg-gray-900 rounded-lg px-3 py-2 text-sm text-white placeholder-gray-500 outline-none"
                    rows={3}
                  />
                ) : (
                  <input
                    type="text"
                    placeholder={field.label}
                    value={(editingProspect as any)[field.key] || ''}
                    onChange={(e) => setEditingProspect({...editingProspect, [field.key]: e.target.value})}
                    className="w-full border border-gray-700 bg-gray-900 rounded-lg px-3 py-2 text-sm text-white placeholder-gray-500 outline-none"
                  />
                )}
              </div>
            ))}
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={editingProspect.emailConsent}
                onChange={(e) => setEditingProspect({...editingProspect, emailConsent: e.target.checked})}
                className="w-4 h-4"
              />
              <span className="text-sm text-gray-400">Email consent granted</span>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={editingProspect.whatsappConsent}
                onChange={(e) => setEditingProspect({...editingProspect, whatsappConsent: e.target.checked})}
                className="w-4 h-4"
              />
              <span className="text-sm text-gray-400">WhatsApp consent granted</span>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={editingProspect.linkedinConsent}
                onChange={(e) => setEditingProspect({...editingProspect, linkedinConsent: e.target.checked})}
                className="w-4 h-4"
              />
              <span className="text-sm text-gray-400">LinkedIn consent granted</span>
            </div>
          </div>
          <div className="mt-4 flex gap-2">
            <Button variant="primary" onClick={async () => {
              try {
                await updateProspect(editingProspect.id, editingProspect);
                setProspects(prospects.map(p => p.id === editingProspect.id ? editingProspect : p));

                // Handle email consent
                const emailConsentCheck = await checkConsent('email', editingProspect.id);
                if (editingProspect.emailConsent && !emailConsentCheck.has_consent) {
                  await grantConsent({ consent_type: 'email', prospect_id: editingProspect.id, source: 'manual' });
                } else if (!editingProspect.emailConsent && emailConsentCheck.has_consent) {
                  await revokeConsent({ consent_type: 'email', prospect_id: editingProspect.id });
                }

                // Handle WhatsApp consent
                const whatsappConsentCheck = await checkConsent('whatsapp', editingProspect.id);
                if (editingProspect.whatsappConsent && !whatsappConsentCheck.has_consent) {
                  await grantConsent({ consent_type: 'whatsapp', prospect_id: editingProspect.id, source: 'manual' });
                } else if (!editingProspect.whatsappConsent && whatsappConsentCheck.has_consent) {
                  await revokeConsent({ consent_type: 'whatsapp', prospect_id: editingProspect.id });
                }

                // Handle LinkedIn consent
                const linkedinConsentCheck = await checkConsent('linkedin', editingProspect.id);
                if (editingProspect.linkedinConsent && !linkedinConsentCheck.has_consent) {
                  await grantConsent({ consent_type: 'linkedin', prospect_id: editingProspect.id, source: 'manual' });
                } else if (!editingProspect.linkedinConsent && linkedinConsentCheck.has_consent) {
                  await revokeConsent({ consent_type: 'linkedin', prospect_id: editingProspect.id });
                }

                setShowEditForm(false);
                setEditingProspect(null);
                setToast({ message: 'Prospect updated!', type: 'success' });
              } catch (err: any) {
                setToast({ message: err.message || 'Failed to update prospect', type: 'error' });
              }
            }}>
              Save Changes
            </Button>
            <Button variant="secondary" onClick={() => {
              setShowEditForm(false);
              setEditingProspect(null);
            }}>
              Cancel
            </Button>
          </div>
        </div>
      )}

        {/* Search and Filter */}
        <div className="flex gap-3 mb-4">
          <input
            type="text"
            placeholder="Search prospects..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="flex-1 border border-gray-700 bg-gray-800 rounded-lg px-3 py-2 text-sm outline-none focus:border-gray-600 text-white placeholder-gray-500"
          />
          <select 
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="border border-gray-700 bg-gray-800 rounded-lg px-3 py-2 text-sm outline-none focus:border-gray-600 text-white"
          >
            <option>All Status</option>
            <option>New</option>
            <option>Contacted</option>
            <option>Responded</option>
            <option>Interested</option>
            <option>Qualified</option>
            <option>Meeting Scheduled</option>
            <option>Follow-up Required</option>
            <option>Not Interested</option>
          </select>
          <select 
            value={interestFilter}
            onChange={(e) => setInterestFilter(e.target.value)}
            className="border border-gray-700 bg-gray-800 rounded-lg px-3 py-2 text-sm outline-none focus:border-gray-600 text-white"
          >
            <option>All Interest</option>
            <option>Low</option>
            <option>Medium</option>
            <option>High</option>
            <option>Very High</option>
          </select>
        </div>

        <div className="bg-gray-800 border border-gray-700 rounded-xl overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-700 bg-gray-800">
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Name</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Position</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Company</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Industry / Notes</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Email</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Phone</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Country</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Status</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Interest</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Email Consent</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Last Contact</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Next Follow-up</th>
                <th className="text-left px-4 py-3 text-xs text-gray-400 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredProspects.map((p) => (
                <tr key={p.id} className="border-b border-gray-700 last:border-0 hover:bg-gray-700 cursor-pointer">
                  <td className="px-4 py-3 text-white font-medium">{p.name}</td>
                  <td className="px-4 py-3 text-gray-400">{p.position}</td>
                  <td className="px-4 py-3 text-gray-500">{p.company}</td>
                  <td className="px-4 py-3 text-gray-500">{p.yacht}</td>
                  <td className="px-4 py-3 text-gray-500">{p.email}</td>
                  <td className="px-4 py-3 text-gray-500">{p.phone}</td>
                  <td className="px-4 py-3 text-gray-500">{p.country}</td>
                  <td className="px-4 py-3">
                    <select 
                      value={p.status}
                      onChange={(e) => handleStatusChange(p.id, e.target.value)}
                      className="text-xs px-2 py-1 rounded-full font-medium bg-gray-700 text-gray-300 border-0 outline-none cursor-pointer"
                    >
                      <option>New</option>
                      <option>Contacted</option>
                      <option>Responded</option>
                      <option>Interested</option>
                      <option>Qualified</option>
                      <option>Meeting Scheduled</option>
                      <option>Follow-up Required</option>
                      <option>Not Interested</option>
                    </select>
                  </td>
                  <td className="px-4 py-3 text-gray-500">{p.interest}</td>
                  <td className="px-4 py-3">
                    <input
                      type="checkbox"
                      checked={p.email_consent || false}
                      onChange={async () => {
                        const previousState = p.email_consent;
                        // Optimistically update UI
                        setProspects(prospects.map(pr => pr.id === p.id ? { ...pr, email_consent: !previousState } : pr));

                        try {
                          if (previousState) {
                            await revokeConsent({ consent_type: 'email', prospect_id: p.id });
                            setToast({ message: 'Email consent revoked', type: 'info' });
                          } else {
                            await grantConsent({ consent_type: 'email', prospect_id: p.id, source: 'manual' });
                            setToast({ message: 'Email consent granted', type: 'success' });
                          }
                          // Refresh to get actual state from backend
                          const data = await getProspects();
                          if (!data.error && Array.isArray(data)) {
                            setProspects(data);
                          }
                        } catch (err: any) {
                          // Rollback on error
                          setProspects(prospects.map(pr => pr.id === p.id ? { ...pr, email_consent: previousState } : pr));
                          setToast({ message: err.message || 'Failed to update consent', type: 'error' });
                        }
                      }}
                      className="w-4 h-4 cursor-pointer"
                    />
                  </td>
                  <td className="px-4 py-3 text-gray-500">{p.lastContact}</td>
                  <td className="px-4 py-3 text-gray-500">{p.nextFollowup}</td>
                  <td className="px-4 py-3">
                    <div className="flex gap-2">
                      <button
                        onClick={async () => {
                          setEditingProspect(p);
                          // Load consent states
                          const emailConsentCheck = await checkConsent('email', p.id);
                          const whatsappConsentCheck = await checkConsent('whatsapp', p.id);
                          const linkedinConsentCheck = await checkConsent('linkedin', p.id);
                          setEditingProspect({
                            ...p,
                            emailConsent: emailConsentCheck.has_consent,
                            whatsappConsent: whatsappConsentCheck.has_consent,
                            linkedinConsent: linkedinConsentCheck.has_consent,
                          });
                          setShowEditForm(true);
                        }}
                        className="text-xs text-blue-400 hover:text-blue-300"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleDelete(p.id)}
                        className="text-xs text-red-400 hover:text-red-300"
                      >
                        Delete
                      </button>
                      <button
                        onClick={async () => {
                          try {
                            const data = await createLead({
                              name: p.name,
                              company: p.company,
                              status: 'New',
                              value: 0,
                              source: 'prospects',
                              prospect_id: p.id,
                            });
                            if (data.error) {
                              setToast({ message: data.error, type: 'error' });
                            } else {
                              setToast({ message: `${p.name} converted to lead!`, type: 'success' });
                              // Remove from prospects list
                              setProspects(prospects.filter(pr => pr.id !== p.id));
                              // Redirect to Leads page
                              router.push('/leads');
                            }
                          } catch (error: any) {
                            console.error('Convert to lead error:', error);
                            setToast({ message: error.message || 'Failed to convert to lead', type: 'error' });
                          }
                        }}
                        className="text-xs text-green-400 hover:text-green-300"
                      >
                        Convert to Lead
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      
      {toast && (
        <Toast 
          message={toast.message} 
          type={toast.type} 
          onClose={() => setToast(null)} 
        />
      )}
    </div>
  );
}
